/* Regeln › Berufe (Grundbuch S. 50–81): sechs Berufe mit Moves und Berufungen, vier Animal Companions, Traits. Deutsche Übersetzung.
   Kartenfarben der Moves: h = Herz (Society), d = Karo (Academia), c = Kreuz (War), s = Pik (Street). Das Gespräch S. 82 ist nicht übernommen. */
(function(){
var K = "haus/regeln/berufe", L = (HH_TEXT[K] = HH_TEXT[K] || []);
var SYM = {h: "{herz}", d: "{karo}", c: "{kreuz}", s: "{pik}"};
function sy(s){ return s.split("").map(function(c){ return SYM[c]; }).join(""); }
var FLD = {Society: "Society {herz}", Academia: "Academia {karo}", War: "War {kreuz}", Street: "Street {pik}"};
/* Move-Karte: Name, Kartenfarben, Text, optionale Voraussetzung */
function M(name, suits, text, req){ return {t: "box", h: name, b: [sy(suits) + (req ? " *" + req + "*" : ""), text]}; }
/* Berufskarte */
function B(name, field, trait, moves, skills){ return {t: "box", h: name, b: ["**Field Point:** " + FLD[field], "**Trait:** " + trait, "**Wähle einen Move:** " + moves, "**Skill Points:** " + skills]}; }
/* Berufungskarte */
function V(name, quote, field, skills, traits, text, extra){ return {t: "box", h: name, b: ["*„" + quote + "“*", "**Field Point:** " + FLD[field] + "  ·  **Skills:** " + skills, "**Wähle einen Trait:** " + traits + (extra || ""), text]}; }
var NW = "Erfordert eine Zweihand-Nahkampfwaffe.", MW = "Erfordert eine Nahkampfwaffe.", DW = "Erfordert eine Duellwaffe.";
var AC = " oder einen Trait deines Animal Companion";

L.push(
{id: "soldiers", t: "Soldiers", p: 50, b: [
 "Es gibt viele Wege, im House ehrlich seinen Lebensunterhalt zu verdienen. Einer davon ist, Soldat zu werden und eine militärische Laufbahn einzuschlagen. Soldaten sind starke, tüchtige Littlings, die sich nicht vor hartem Training scheuen, um sich auf einen noch härteren Beruf vorzubereiten. Manche stammen aus vielfach ausgezeichneten Familien und wollen eine lange militärische Tradition ehren. Andere kommen aus Armut oder in der Hoffnung, zu reisen und unabhängig zu werden, zu diesem Beruf. Aus welchem Grund auch immer: Sich zu verpflichten war schon immer einfach und wird es leider wohl noch lange bleiben. Der First Household War ist zwar vorbei, aber die Nachfrage nach Littlings, die bereit sind, ein angemessenes Maß an Gewalt auszuüben, ist weiterhin hoch.",
 "Das ist der Beruf der Soldaten aller Armeen und Nationen, aber auch der Söldner, die ihre Schwerter an den Meistbietenden verkaufen, sowie der Wachen und Gendarmen, die als Polizeikorps arbeiten. Weitere Littlings, die etwas weniger direkt in diese Kategorie fallen, sind gefährliche Raufbolde und alle, die reichen Kaufleuten oder Adligen als Leibwächter folgen. Diese Leute sind sehr gefragt und stehen ihrem Arbeitgeber meist näher als sein engster Berater. Manche von euch kennen vielleicht die Geschichte des Boggarts, der als Leibwächter für Vin De Champagne arbeitete und bei drei verschiedenen Gelegenheiten eine Kugel für seinen Arbeitgeber abfing. Zum Zeitpunkt seines Todes vermachte der reiche Fairy sein gesamtes Vermögen dem Boggart und ließ seine drei Kinder mittellos zurück.",
 {t: "h", x: "Soldier-Moves"},
 {t: "karten", x: [
  M("Bodyguard", "hc", "Erleidet ein Freund Stress und/oder einen Zustand, kannst du dich entscheiden, ihn auf dich zu nehmen."),
  M("Defensive Stance", "dc", "Alle deine Freunde erhalten +1 auf ihren nächsten Reaction Roll gegen einen Gegner.", NW),
  M("Endure Pain", "c", "Entferne einen einzelnen Zustand von dir. Den Zustand Gebrochen kannst du so nicht entfernen."),
  M("Power Through", "cs", "Du kannst gegen einen Gegner mit Will +1 reagieren, statt mit dem verlangten Skill."),
  M("Charge!", "c", "Beim ersten Angriff auf einen Gegner verursachst du 1 zusätzlichen Stress.", MW),
  M("Hold them Back", "hc", "Du erleidest −2 auf deinen aktuellen Reaction Roll gegen einen Gegner. Alle deine Freunde bestehen denselben Reaction Roll automatisch und können den Kampf verlassen.", NW),
  M("Spin Attack", "c", "Nachdem du einen Gegner getroffen hast, kannst du einen zweiten Action Roll mit −1 ablegen.", NW),
  M("Two on One", "h", "Du und ein Freund erhaltet +1 auf euren nächsten Wurf auf Fight.")]},
 {t: "h", x: "Der Beruf"},
 B("Soldier", "War", "Master at Arms", "Bodyguard, Defensive Stance, Endure Pain oder Power Through", "Care, Craft, Investigation, Athletics, Authority, Fight, Strength, Will, Caution, Shoot"),
 {t: "h", x: "Berufungen"},
 {t: "karten", x: [
  V("Cadet", "Was ist schon dabei, zwischen zwei Schlachten ein bisschen leben zu wollen?", "Society", "Art, Charm, Etiquette, Grace, Culture, Insight, Athletics, Fight, Dexterity, Elusion", "Heartbreaker, Well-Trained oder Well-Mannered", "Junge Littlings mit großen Hoffnungen und gutem Aussehen: Cadets sind eher an Hofbälle gewöhnt als an das Leben an der Front. Sie verlassen sich auf den Charme der Uniform, um überall im House Herzen zu brechen. Unter ihnen gibt es die Ehrengarde, die Adlige und Würdenträger des Realm auf ihren Reisen durch das House begleitet oder sogar in Highlight Wache steht."),
  V("Gendarme", "Weitergehen. Weitergehen, sagte ich! Hier gibt es nichts zu sehen!", "Academia", "Eloquence, Etiquette, Craft, Insight, Investigation, Authority, Will, Caution, Elusion, Shoot", "Sixth Sense, From the Gutter oder Alert", "Gendarmen sind Polizeibeamte, die die Städte vor Verbrechern und Rowdys schützen. Im Realm gehören sie der Royal Gendarmerie an und tragen grüne Uniformen. Im Hearth tragen sie hellblaue Hemden und unterstehen direkt dem Sheriff ihres Countys. In den Freedomes fallen ihre roten Jacken auf den überfüllten Märkten auf, und sie sind berühmt für ihre Effizienz. In der Horde schließlich heißen sie Miliz und haben die harte Aufgabe, den illegalen Warenhandel im Basement einzudämmen."),
  V("Guardian", "Bleib dicht bei mir. Und wenn es schlimm wird, überlass es mir.", "Society", "Art, Eloquence, Care, Craft, Insight, Fight, Strength, Will, Caution, Exploration", "Big and Strong, Brawler oder Selfless", "Ob als Soldat auf einer Mission oder als Söldner, der als Leibwächter angeheuert wurde: Auf einen Guardian kannst du dich in der Not immer verlassen. Diese Littlings sind darauf trainiert, andere zu verteidigen, und erfüllen ihre Pflicht ausnahmslos bewundernswert. Manche arbeiten als Eskorte für die Handelskarawanen, die täglich die Free Dominions und den Hearth durchqueren, andere reisen mit Hunters auf deren gefährlichsten Expeditionen."),
  V("Officer", "Littlings! Auf mein Kommando!", "Academia", "Eloquence, Etiquette, Charm, Care, Culture, Insight, Authority, Fight, Will, Shoot", "Natural Born Leader, Tough as a Nail oder Mediator", "Hochrangige Mitglieder der Armee, wichtige Vorbilder für ihre Mitsoldaten oder Veteranen der größten Schlachten des House: Officers sind charismatische und unbeugsame Anführer. Ihre mutigen Taten und Reden können Herzen stärken und Soldaten zum Sieg führen. Disziplinierte und gebildete Littlings, die Militärgruppen befehligen und anspruchsvolle Titel wie „Sergeant“, „Brigadier“ oder „Captain“ tragen."),
  V("First-Class", "Wir sind die Besten der Besten.", "Academia", "Etiquette, Grace, Culture, Athletics, Fight, Strength, Will, Dexterity, Exploration, Shoot", "Big and Strong, Braveheart oder Well-trained", "First-Class-Soldaten erhalten die beste Ausbildung im House. Manche dienen in der Great Imperial Army, nachdem sie die Glasburg Academy im Cupboard besucht haben, andere, die Warriors of the Great Blade, gehören zur Horde Army. Und vergessen wir nicht die Soldaten der Porcelain Army der Free Dominions mit ihren erstaunlichen Emaille-Kürassen und die Garnisonen der Hearth Army, die regelmäßig gerufen werden, um dem Realm bei seinen Auslandseinsätzen zu helfen."),
  V("Scissor for Hire", "Das House ist ein gefährlicher Ort. Ich kann dir helfen … gegen die richtige Gebühr, versteht sich.", "Street", "Charm, Care, Craft, Authority, Fight, Strength, Will, Caution, Elusion, Exploration", "Tough as a Nail, Big and Strong oder Brawler", "In jeder anständigen Taverne, von den Tiefen des Basement bis zum Upper Floor der Freedomes, gibt es immer einen Scissor for Hire, der Arbeit sucht. Littlings mit wenigen Worten und großen Taten: Diese Glücksritter bieten ihre Dienste dem Meistbietenden an und sind meist vertrauenswürdig. Manche arbeiten für organisierte Gruppen, manche auf eigene Faust, aber alle scheinen wenigstens eine Art Ehrenkodex zu haben.")]}
]},

{id: "scholars", t: "Scholars", p: 54, b: [
 "Es stimmt, dass Soldaten und Hunters unsere Nationen verteidigen, doch die Scholars sind es, die sie voranführen. Diese Littlings von großer Bildung und scharfem Verstand werden Jahr für Jahr an Universitäten und Akademien im ganzen House ausgebildet und werden zum Quell von Stolz und Inspiration für alle, die sich eine bessere Zukunft wünschen. Nach dem First Household War ist die Nachfrage nach Scholars in allen Bereichen spürbar gewachsen, und die offenen Grenzen haben es Völkern und Nationen noch leichter gemacht, ihre verschiedenen Methoden und Entdeckungen miteinander zu teilen. Für alle Littlings der Wissenschaft, Kunst und Kultur ist dies eine blühende Zeit voller beispielloser Möglichkeiten.",
 "Das ist der Beruf aller Littlings, die sich darauf konzentrieren, ein oder mehrere Fächer eingehend zu studieren. Beispiele sind Würdenträger, Botschafter und Diplomaten, die in ihrer Heimat oder im Ausland arbeiten, ebenso Ärzte und Chirurgen, Ingenieure, Architekten, Botaniker und Alchemisten, aber auch Philosophen, Kartografen und Historiker. Nicht zu vergessen sind Künstler und Kunsttheoretiker, Kritiker und namhafte Stylisten, Komponisten, Musiker, Gastronomen und Feinschmecker sowie Rechtsmediziner und große Detektive. Dann gibt es Pädagogen und Erzieher, Etikette-Experten und Adepten der Liebeskunst, Sprachforscher und sogar Dichter oder Schriftsteller, wie meine Wenigkeit.",
 {t: "h", x: "Scholar-Moves"},
 {t: "karten", x: [
  M("Attention to Details", "hd", "Entweder bitte die Spielleitung um einen Hinweis oder Vorschlag, oder finde den Weak Spot eines Gegners."),
  M("Do you know who I am!", "hc", "Du kannst gegen einen Littling mit Authority +1 reagieren, statt mit dem verlangten Skill."),
  M("Fast Learning", "d", "Hat ein Freund einen Wurf bestanden, bestehst du denselben Wurf, ohne zu würfeln."),
  M("Soothe Pain", "hd", "Entferne einen einzelnen Zustand von einem Freund. Den Zustand Gebrochen kannst du so nicht entfernen."),
  M("Tinker", "d", "Entweder repariere etwas, oder finde, richte neu ein oder baue ein Gadget."),
  M("Friends in High Places", "h", "Erhalte Informationen oder Ressourcen dank deiner Verbindungen zur High Society oder deiner Berühmtheit."),
  M("Money to Spare", "d", "Bezahle ein Stück Ausrüstung, Waren oder eine Dienstleistung, ohne Coins auszugeben."),
  M("Outsmart", "s", "Du kannst einen Wurf beliebiger Art mit Culture ablegen, statt mit dem verlangten Skill."),
  M("Talk to the Crowd", "hd", "Erlange die Aufmerksamkeit oder Hilfe einer großen Gruppe von Littlings in deiner Nähe."),
  M("Unsolicited Advice", "ds", "Du mischst dich mit ungebetenem Rat ein. Entweder erhält ein Freund +1 auf seinen nächsten Action Roll und erleidet 1 Stress, oder du lenkst einen Littling mit deinen Worten ab.")]},
 {t: "h", x: "Der Beruf"},
 B("Scholar", "Academia", "Know-it-all", "Attention to Details, Do You Know Who I Am?, Fast Learning, Soothe Pain oder Tinker", "Art, Eloquence, Etiquette, Care, Craft, Culture, Insight, Investigation, Caution, Elusion"),
 {t: "h", x: "Berufungen"},
 {t: "karten", x: [
  V("Artist", "Et voilà! Wieder ein Meisterwerk vollendet!", "Society", "Art, Charm, Etiquette, Grace, Care, Craft, Insight, Athletics, Dexterity, Elusion", "Gifted Performer, Master Artisan oder Acrobat", "Musiker, Maler, Akrobaten, Dichter, Schauspieler und so weiter und so fort! Artists sind das schlagende Herz des Household. Kreative Genies von der Universität von Viletia oder Straßenakrobaten, Meisterkomponisten mit Abschluss am Piano oder umherziehende Illustratoren ohne einen Penny: Diese Littlings wissen immer, wie man ein Publikum fesselt. Besonders in der Horde stehen Artists, allen voran Dichter, in hohem Ansehen, und es gibt keinen Hof eines Emirs ohne einen."),
  V("Doctor", "Bitte halten Sie still. Das tut nur ein bisschen weh …", "War", "Etiquette, Care, Craft, Culture, Authority, Fight, Strength, Will, Caution, Dexterity", "Physician, Selfless oder Braveheart", "Von allen Scholars sind Doctors diejenigen, die man meist am wenigsten gern sieht. Doch man kann es ihnen nicht verübeln. Diese Akademiker unter den Akademikern können jede Wunde und jedes Leiden behandeln, aber ihre Methoden sind nicht immer zart. Die berühmtesten unter ihnen sind zweifellos die Absolventen der angesehenen Fakultät für Medizin und Chirurgie in Tuberdam, geleitet von keinem Geringeren als Dr. Werner Reinhardt."),
  V("Diplomat", "Meiner bescheidenen Meinung nach ist es für beide beteiligten Parteien stets von Vorteil, gemeinsam eine Einigung zu finden. Seid Ihr nicht auch dieser Ansicht?", "Society", "Art, Eloquence, Etiquette, Grace, Culture, Insight, Authority, Will, Caution, Elusion", "Well-Mannered, Polyglot oder Mediator", "Botschafter, Hauslehrer und Vermittler aller Art: Diplomats verdienen ihren Lebensunterhalt dank ihrer tadellosen Manieren und ihres charismatischen Debattiergeschicks. Für viele junge Littlings ist das Studium und das Leben als Diplomat ein großartiger Weg, Zugang zum luxuriösen Leben bei Hof zu erlangen und Teil der High Society zu werden."),
  V("Detective", "Ein weiterer Fall, der zu lösen ist. Ein weiteres Geheimnis, das gelüftet wird.", "Street", "Eloquence, Craft, Culture, Insight, Investigation, Authority, Fight, Caution, Elusion, Shoot", "Sixth Sense, Forensic Science oder Alert", "Detectives sind wohl die gefeiertsten Scholars im House. Ihre Taten werden nicht selten zum Gegenstand von Zeitungsartikeln, die alle wie echte Abenteuerromane in Atem halten. Manche sind selbstständig und haben eine eigene Agentur, andere arbeiten für die Strafverfolgung. Die Universität von Tuberdam hat kürzlich eine Fakultät für Forensik eröffnet, die mit ihrem hochmodernen Ansatz Tag für Tag eine neue Generation von Detectives für das House ausbildet."),
  V("Researcher", "Meine lebenslange Forschung trägt endlich Früchte. Wir sind der Wahrheit ganz nah!", "Society", "Charm, Eloquence, Culture, Insight, Investigation, Athletics, Fight, Will, Elusion, Exploration", "Librarian, Polyglot oder Pathfinder", "Wenn irgendwo da draußen etwas darauf wartet, gefunden zu werden, dann sucht dort auch ein Researcher danach. Manche dieser gebildeten Littlings konzentrieren sich auf Geschichte, andere sind geschickte Kartografen, die versuchen, das House zu kartieren, wieder andere Botaniker, die nach kostbaren und seltenen Pilzen suchen. Und wie könnten wir die Littlings vergessen, die nach Relikten und Geheimnissen suchen, echte Schatzjäger, angetrieben von ihrem Durst nach Wissen und Wahrheit."),
  V("Scientist", "Es könnte funktionieren! Nun ja, vielleicht nicht so – hust hust –, aber wenn ich das hier drehe, dann …", "Street", "Grace, Craft, Culture, Authority, Fight, Strength, Caution, Dexterity, Exploration, Shoot", "Master Artisan, Engineer oder Librarian", "Mechaniker, Ingenieure, Botaniker, Uhrmacher, Zoologen und Alchemisten: All diese Littlings aus Theorie und Praxis haben sich den Titel Scientist zweifellos verdient, denn sie alle teilen eine Leidenschaft für einen oder mehrere Zweige der Wissenschaft. Oft treiben diese Scholars ihre Ideen ins Extreme und stecken immer mitten in irgendeinem seltsamen Experiment oder einer Forschung. So oder so steht ihr Gedankengang nie still!")]}
]},

{id: "hunters", t: "Hunters", p: 58, b: [
 "Wilde Mäuse, Ratten, Tausendfüßler und Spinnen aller Formen und Größen streifen durch die Lande des House und kriechen durch die Carpets und Inbetweens. Kein Littling kann sich wirklich sicher fühlen, wenn er einen Fuß über die Grenzen seiner Siedlung setzt, am wenigsten bei einer langen Reise mit einer Packschnecke oder als Teil einer langsamen Handelskarawane. Diese Kreaturen sind eine wahre Plage, die wir, soweit wir wissen, nie ganz loswerden. Die tapferen Hunters sind Littlings, die ihr Leben dem Kampf widmen, diese Bestien aus unserem Land zu vertreiben, und ihnen geht die Arbeit nie aus. In vielen Städten gibt es sogar Tavernen oder Ställe, in denen Gruppen von Hunters ihre Tage mit Trinken und Lachen verbringen, während sie darauf warten, dass die Arbeit zu ihnen kommt.",
 "Das ist der Beruf freiberuflicher Hunters und derer, die als Mitglieder eines Den arbeiten, aber auch der Ranger in vielen Polizeikräften und der Wilderer, die auf leichtes Geld aus sind. Viele der Wachposten, die die Grenzen und Hallways patrouillieren, sind geschickte Hunters, ausgebildet darin, Spuren zu verfolgen und sich unbemerkt durch Schimmel und Pilze zu bewegen. Weitere Beispiele sind die vielen Führer, die Reisende durch unbekannte Lande begleiten oder Abenteurer in die Tiefen der Inbetweens führen, um nach verlorenen Schätzen zu suchen.",
 {t: "h", x: "Hunter-Moves"},
 {t: "karten", x: [
  M("Fast Reload", "cs", "Lade eine Fernkampfwaffe oder Feuerwaffe nach."),
  M("Sharp Eye", "ds", "Entweder finde wichtige Hinweise dank deines scharfen Auges, oder erfahre den Weak Spot des Gegners."),
  M("Take Cover!", "hs", "Entweder verstecken du und ein Freund euch schnell, oder du und/oder ein Freund weicht automatisch einigen Kugeln, einem Angriff oder einem Move eines Large-, Huge-, Giant- oder Flying-Gegners aus, ohne zu würfeln."),
  M("Find Resources", "ds", "Entweder finde Nahrung, improvisierte Waffen, Munition oder ähnlich wichtige Ressourcen dank deines Verstands und deiner Kenntnis der Wildnis, oder finde, richte neu ein oder baue ein Gadget."),
  M("Precision Shot", "ds", "Wiederhole einen Wurf auf Shoot und ignoriere dabei alle Zustände."),
  M("Quick Reaction", "s", "Entweder weiche nach einem misslungenen Reaction Roll einem Hinterhalt aus, oder erhalte +1 auf deinen nächsten Reaction Roll gegen eine Bestie."),
  M("Rescue", "h", "Entweder verhindere, dass ein Freund den Zustand Gebrochen erleidet, oder rette einen Freund davor, Bow Out zu müssen, ohne einen Joker auszugeben."),
  M("Slay", "c", "Nachdem du einen Large-, Huge- oder Giant-Gegner getroffen hast, kannst du einen zweiten Action Roll mit −1 ablegen.")]},
 {t: "h", x: "Der Beruf"},
 B("Hunter", "Street", "Sharpshooter", "Fast Reload, Find Resources, Sharp Eye oder Take Cover!", "Care, Craft, Investigation, Athletics, Fight, Will, Caution, Elusion, Exploration, Shoot"),
 {t: "h", x: "Berufungen"},
 {t: "karten", x: [
  V("Guide", "Hier entlang! Vertrau mir, ich weiß genau, wohin wir gehen.", "Society", "Eloquence, Etiquette, Grace, Care, Culture, Insight, Caution, Elusion, Exploration, Shoot", "Pathfinder, Polyglot oder Alert", "Vom Waxy Swale des Realm bis zur Sawdust Waste unten im Basement, quer durch den Long Hallway und die steilen Stairs: Die wildesten Orte im House stellen Reisende und Karawanen vor große Herausforderungen. Zum Glück gibt es Guides, erfahrene Hunters und erstklassige Entdecker, die wissen, wie man jeder Gefahr ausweicht und, wenn es sein muss, ihr entgegentritt."),
  V("Champion", "Und habe ich dir schon erzählt, wie ich einer Wolfsspinne mal direkt zwischen die Augen geschlagen habe?", "Society", "Charm, Etiquette, Craft, Athletics, Authority, Fight, Strength, Will, Exploration, Shoot", "Braveheart, Big and Strong oder Beastmaster", "Champions sind liebenswerte Angeber, die die Tavernen mit ihren Jagdtrophäen füllen und am Feuer immer ein oder zwei Dutzend Geschichten zu erzählen haben. Viele gehören einem Den an, einer Gilde von Hunters, die dasselbe Symbol und denselben Verhaltenskodex teilen. Die berühmtesten sind der Deadmouse Den in Wallford, der Goldwing Den im Realm und der Broken Key unten im Basement."),
  V("Nomad", "Das House ist meine Straße. Die Straße ist mein Zuhause.", "Academia", "Care, Craft, Culture, Insight, Athletics, Fight, Strength, Will, Elusion, Exploration", "Pathfinder, Physician oder Camouflage", "Wie der Name schon sagt, sind Nomads Hunters ohne festen Wohnsitz, die ständig unterwegs sind, um die wilden Einöden des House zu erkunden oder zu bestreifen. Zu ihnen zählen die Littlings der heißen Kashab, der Sawdust Desert im Licht des ewigen Sonnenuntergangs, aber auch die Pioniere der Carpet Plains rund um den Yule Tree im Living Room."),
  V("Scout", "Hörst du diese Stille? Jemand wartet auf uns …", "War", "Eloquence, Grace, Insight, Athletics, Strength, Caution, Dexterity, Elusion, Exploration, Shoot", "Alert, Deadeye oder Camouflage", "Wachsam und leise: Scouts sind äußerst geschickte Entdecker, die ein Lager schützen oder Aufklärung betreiben. Manche dieser Hunters sind waschechte Soldaten, wie die, die an der Royal Army Academy im Cupboard studieren. Diese Littlings werden oft in andere Nationen oder gemeinsame Gebiete wie die Short und Long Hallway oder die Great Stairs entsandt, um die gegnerischen Armeen im Auge zu behalten."),
  V("Lone Mouse", "Ist mir egal. Nicht mein Problem. Ich mache nur meinen Job.", "War", "Care, Craft, Insight, Athletics, Authority, Fight, Strength, Will, Caution, Shoot", "Deadeye, Pathfinder oder Beastmaster", "Manchen Hunters geht es nur um die Jagd, sei es, um eine gefährliche Bestie aufzuspüren oder um eine Beute aus Fellen und Panzern zu verdienen, die sie auf dem Markt verkaufen. Manche dieser Lone Mice arbeiten nur für sich, andere lassen sich als Söldner für Privatkunden oder die Handelskorporationen des Upper Floor anheuern. Aber alle sind distanzierte Einzelgänger, echte harte Kerle!"),
  V("Bounty Hunter", "Mach nicht so ein Gesicht. Jemand ist bereit, viel Geld zu zahlen, um dich zu sehen. Freust du dich nicht?", "War", "Charm, Eloquence, Insight, Investigation, Authority, Fight, Will, Dexterity, Elusion, Shoot", "Tough as a Nail, Sixth Sense oder Nail Thrower", "Nicht alle Hunters jagen Insekten und große Ratten. Manche jagen lieber Littlings, die das Gesetz gebrochen oder sich irgendwo in der Stadt gefährliche Feinde gemacht haben. Bounty Hunters haben den Ruf rücksichtsloser Söldner, und manche sind es wirklich. Andere aber werden von einem tiefen Gerechtigkeitssinn angetrieben oder sind im Dienst des Gemeinwohls unterwegs.")]}
]},

{id: "criminals", t: "Criminals", p: 62, b: [
 "Solange es ehrliche Littlings gibt, die für ehrlichen Lohn arbeiten wollen, wird es auch andere geben, die versuchen, sie auszunutzen. Ich kann das Verbrecherleben ehrlich gesagt nicht als echten Beruf bezeichnen, aber verzweifelte Zeiten verlangen manchmal verzweifelte Lösungen. Der Krieg hat die Bewohner des Household nachhaltig gezeichnet, und viele fanden sich in bitterer Armut wieder. Manche von ihnen hatten keine andere Wahl, als sich kleinen Diebstählen und gelegentlichen Betrügereien zuzuwenden, um zu überleben, und stellten dann fest, dass sie in einer dunklen, beängstigenden Welt gefangen waren, aus der sie nicht mehr entkommen können. Andere sind einfach Gauner, doch auch sie haben ihren Platz und eine wichtige Rolle in den Augen der Geschichte.",
 "Das ist der Beruf der Schwindler, Drückeberger und Betrüger aller Art, mit ihrem breiten Lächeln und offenen Taschen, begierig darauf, gefüllt zu werden. Es ist das Feld der flinkfingrigen Diebe, die uns bereitwillig von unseren Börsen erleichtern, aber auch der Falschspieler, die letztlich dasselbe tun. Und vergessen wir nicht die Fälscher, wahre Künstler des Verbrechens, und all die begabten Schauspieler, die Hochstapler und Betrüger sind. Manche schleichen in Häuser und Villen, ohne eine Spur zu hinterlassen, manche bearbeiten Schlösser und Tresore mit der Präzision eines Chirurgen, dazu die freundlichen Apotheker mit ihren unsichtbaren Giften. Schließlich gibt es Banditen, Halsabschneider und Auftragsmörder, denen Geld nicht genügt und die auch Leben stehlen.",
 {t: "h", x: "Criminal-Moves"},
 {t: "karten", x: [
  M("Expedient", "s", "Entweder bringst du dich und einen Freund aus einer gefährlichen Lage, oder ihr verlasst beide einen Kampf."),
  M("I Heard a Rumor!", "hd", "Entweder kennst du eine heikle Information aus dem Klatsch – du darfst sie dir ausdenken oder die Spielleitung fragen –, oder du setzt selbst ein Gerücht in die Welt."),
  M("Jack of all Trades", "s", "Erhalte +1 auf deinen nächsten Wurf."),
  M("Learn from Mistakes", "s", "Hat ein Freund einen Wurf verpatzt, bestehst du ihn automatisch, ohne zu würfeln."),
  M("Your Loss, My Gain", "hs", "Ein Freund trägt die Folgen deines Misserfolgs statt dir."),
  M("Ambush", "cs", "Schlage einen ahnungslosen Littling leise nieder, ohne Aufmerksamkeit zu erregen."),
  M("Concealed Nail", "s", "Du hast eine versteckte Nail bei dir oder kannst eine finden."),
  M("Friends in Low Places", "hs", "Erhalte Informationen oder Ressourcen dank deiner Verbindungen zur Unterwelt oder deines kriminellen Rufs."),
  M("Fiddling", "d", "Entweder knacke ein Schloss, oder finde, richte neu ein oder baue ein Gadget."),
  M("Sleight of Hand", "s", "Entweder stiehl einen kleinen Gegenstand in Reichweite, oder erhalte alle Coins zurück, die du für ein Stück Ausrüstung, Waren oder eine Dienstleistung ausgegeben hast.")]},
 {t: "h", x: "Der Beruf"},
 B("Criminal", "Street", "Shadow", "Expedient, I Heard a Rumor, Jack of all Trades, Learn from Mistakes oder Your Loss, My Gain", "Eloquence, Grace, Insight, Investigation, Athletics, Authority, Fight, Caution, Dexterity, Elusion"),
 {t: "h", x: "Berufungen"},
 {t: "karten", x: [
  V("Courtesan", "Sollen wir heute Abend tanzen gehen?", "Society", "Art, Charm, Etiquette, Grace, Care, Authority, Fight, Will, Dexterity, Elusion", "Well-Mannered, Heartbreaker oder Gifted Performer", "Wenn du durch die Hauptstraßen der Städte des Household gehst, stolperst du oft über private Clubs und Spielhäuser mit einer Kundschaft aus Littlings der High Society. Diese Orte werden stets von Courtesans und Begleiterinnen besucht, die auf fremde Kosten gut leben wollen und bereit sind, zerstreute Geldsäcke auszunutzen, die manchmal vergessen, dass sie verheiratet sind. Im Realm tragen Courtesans oft kleine Zierflügel, manchmal schändlich rot bemalt, wie die der Tsarina."),
  V("Cheater", "Du bist ein kluger Kerl, das sieht man. Und du weißt, dass ich dich niemals belügen könnte!", "Society", "Eloquence, Etiquette, Grace, Care, Culture, Insight, Athletics, Caution, Dexterity, Elusion", "Well-Mannered, Perfect Liar oder Polyglot", "Das Verbrechen der Wahl für Cheaters ist ein opferloses, und letztlich bleiben sie oft bei bloßem Lügen für ihren Job. Manche dieser Criminals haften sich wie Schimmel an einen Adligen oder reichen Littling und rupfen ihn Stück für Stück, andere verkaufen Wunderelixiere auf Straßenmärkten. Was sie alle teilen, ist der honigsüße Opportunismus und das Talent, anderen mit einem Lächeln die Taschen zu leeren."),
  V("Thief", "Ich arbeite in der Umverteilung von Vermögen und unbefristeten Darlehen.", "Academia", "Eloquence, Grace, Craft, Insight, Investigation, Athletics, Fight, Caution, Dexterity, Elusion", "Pickpocket, Picklock oder Acrobat", "Lange, schmale Finger, die in die tiefen Taschen der Reichsten der Stadt tauchen. Scharfe Köpfe, die jede Kombination knacken und jedes Schloss öffnen. Man muss es den Thieves lassen: Sie gehören zu den geschicktesten Criminals überhaupt. Manche begnügen sich damit, sich auf Kosten eines zerstreuten Littlings zu bereichern. Andere sind wahre kriminelle Genies, die nur die spektakulärsten Coups wollen und gern in der Zeitung von ihren Taten lesen."),
  V("Professional", "Es ist harte Arbeit, aber irgendjemand muss sie ja tun …", "Academia", "Art, Etiquette, Grace, Care, Craft, Culture, Insight, Authority, Dexterity, Shoot", "Counterfeiter, Physician oder Engineer", "Wenn du einen Coup durchziehen willst, der der Geschichtsbücher würdig ist, brauchst du einen echten Professional. Diese Criminals sind Ärzte ohne Zulassung, die Littlings ohne Fragen zusammenflicken. Erstklassige Fälscher, die Kunstwerke und offizielle Dokumente für jeden Anlass nachbilden. Aus ihren Universitäten oder Praxen verstoßene Wissenschaftler, die ihren Mut in den Dienst krimineller Ringe stellen."),
  V("Snitch", "Du würdest nicht glauben, was ich gesehen habe.", "Academia", "Eloquence, Culture, Insight, Investigation, Athletics, Will, Fight, Caution, Elusion, Shoot", "From the Gutter, Perfect Liar oder Sixth Sense", "Manchmal sind Informationen mehr wert als Geld. Das wissen Snitches sehr gut, denn sie machen eine Karriere daraus, private Informationen zu sammeln und zu verkaufen. Manche arbeiten mit den Ringen in Unter oder Tuberdam zusammen, andere sind verdeckte Agenten der Strafverfolgung. Wieder andere arbeiten nur für sich und versuchen, Stück für Stück mit Insiderwissen in die High Society aufzusteigen."),
  V("Thug", "Ein Schlag auf den Kopf, und die Sache ist erledigt. Kein Grund, es in die Länge zu ziehen.", "War", "Charm, Craft, Athletics, Authority, Fight, Strength, Will, Caution, Exploration, Shoot", "Big and Strong, Tough as a Nail oder Brawler", "Die feine Kunst der Täuschung, die leichte Hand flinker Finger und die exakte Wissenschaft des Einbruchs sind nicht die besten Eigenschaften eines Thugs. Sie gehen lieber grob vor. In den weiten Carpet Plains oder im Pinewood Forest kann ein Littling sich zum Beispiel Zeit nehmen, einen Hinterhalt zu legen und auf die nächste Handelskarawane oder die nächste Gruppe von Hunters zu lauern, die von einer harten Jagd zurückkehrt.")]}
]},

{id: "duelists", t: "Duelists", p: 66, b: [
 "Der First Household War hat das Household und seine Bewohner nachhaltig gezeichnet. Die Welt hat sich in wenigen Jahren tiefgreifend und radikal verändert, und die neu erfundenen Technologien löschten ganze Berufe aus und stellten uralte Traditionen auf den Kopf. Duelists sind die Hüter einer alten Kunst, die in alten Akademien weitergegeben wird, einer Kriegskunst, die entstand, als Krieg noch eine sauberere, romantischere Angelegenheit war, als das Können des Kämpfers auf dem Schlachtfeld wirklich einen Unterschied machte. Alle lieben sie, denn sie sind die letzten Überbleibsel einer einfacheren Zeit, die unseren Geist und unser Herz in ein Zeitalter der Märchen, großen Taten und unsterblichen Lieben zurückversetzen.",
 "Das ist der Beruf all derer, die die Kunst des Duellierens in einer Schule oder bei einem Meister gelernt und zu ihrem Lebensstil gemacht haben. Diese Littlings verdienen ihren Lebensunterhalt entweder damit, ihre Kunst weiterzugeben, oder im Dienst reicher Kaufleute und Adliger. Manchmal ist ihr Ruhm so groß, dass ein Mächtiger sie tatsächlich zu einer echten Quest ruft.",
 {t: "h", x: "Fechtakademien"},
 "An der Fencing Academy in Faeriyev lernen die Schüler die elegante und präzise Kunst der Nadel (Pin), während die Hearth Academy in Wallford die Duell-Halbschere bevorzugt. Unten im Basement folgt die Academia am Mirandola Gulf dem Weg der Lancetta. Auf dem Upper Floor schließlich gibt die Academy der Free Dominions in der Vanity den Schneiderstil der Needle weiter.",
 {t: "h", x: "Duelist-Moves"},
 {t: "karten", x: [
  M("Cunning Tactics", "ds", "Entweder finde den Weak Spot eines Littling-Gegners, oder vermeide alle Effekte des Moves eines Littling-Gegners."),
  M("En Garde", "hc", "Du und ein Freund erhaltet +1 auf euren nächsten Reaction Roll gegen einen Littling-Gegner.", DW),
  M("Bravado", "cs", "Ohne zu würfeln kannst du Kugeln ausweichen, ein gefährliches Kunststück vollbringen, die Folgen eines Sturzes vermeiden oder einen Kampf verlassen."),
  M("Riposte", "c", "Du kannst gegen einen Littling-Gegner mit Fight +1 reagieren, statt mit dem verlangten Skill.", DW),
  M("Feint", "cs", "Wiederhole einen einzelnen Action Roll gegen einen Littling-Gegner; du hast +1 auf den Wurf und ignorierst alle Zustände.", DW),
  M("Broken Time", "c", "Nachdem du einen Littling getroffen hast, kannst du einen zweiten Action Roll mit −1 ablegen.", DW),
  M("Make an Entrance", "hs", "Tritt sofort in einen Kampf ein und führe einen Action Turn aus, selbst wenn du weit vom Gegner entfernt oder anderweitig beschäftigt warst.", DW),
  M("Vendetta", "s", "Nach einem misslungenen Reaction Roll gegen einen Littling-Gegner verursachst du bei ihm 1 Stress.", DW)]},
 {t: "h", x: "Der Beruf"},
 B("Duelist", "War", "Swordfighter", "Cunning Tactics, En Garde, Bravado oder Riposte", "Charm, Etiquette, Grace, Culture, Insight, Athletics, Authority, Fight, Dexterity, Elusion"),
 {t: "h", x: "Berufungen"},
 {t: "karten", x: [
  V("Libertine", "Bezaubert, Eure Bekanntschaft zu machen. Selbst der Chandelier verblasst vor Eurer Schönheit.", "Society", "Art, Charm, Eloquence, Etiquette, Grace, Care, Insight, Investigation, Fight, Elusion", "Heartbreaker, Well-Mannered oder Perfect Liar", "Wer kann dem zeitlosen Charme eines Duelists widerstehen? Libertines sind eindeutig die galantesten und charismatischsten Fechter im House. Sie sind dafür bekannt, ebenso tödliche Kämpfer wie hoffnungslose Romantiker zu sein. Ihre Eleganz fällt auf dem Schlachtfeld wie im Ballsaal auf, und manchmal sieht man sie im Morgengrauen vom Fenster eines reichen Fangs hinabhasten."),
  V("Captain", "Folgt mir, und ich führe euch zum Sieg!", "Academia", "Eloquence, Etiquette, Grace, Care, Insight, Investigation, Authority, Fight, Will, Caution", "Tough as a Nail, Well-Mannered oder Natural Born Leader", "Captains sind erfahrene Duelists, die ihre Littlings mit Stärke und Entschlossenheit führen. Manche sind echte Soldaten, geschmiedet in erstklassigen Akademien wie der unter dem Great Window oder der in Viletia am Mirandola Gulf. Andere sind Söldner, die einem äußerst strengen Ehrenkodex folgen, oder sogar Deserteure und Dissidenten, die zum Sprachrohr gegen Ungerechtigkeit werden."),
  V("Hero", "Meine Halbschere verteidigt die Schwachen und schlägt das Böse nieder. Am Ende siegt das Gute.", "Society", "Charm, Grace, Care, Craft, Athletics, Authority, Fight, Strength, Will, Caution", "Braveheart, Natural Born Leader oder Selfless", "Wo es Verbrechen und Ungerechtigkeit gibt, gibt es immer einen Hero, der sie bekämpft. Duelists, bewaffnet mit Klinge und Ehre, Littlings mit hohen Idealen, die stets an vorderster Front stehen, um Bedürftige zu verteidigen. Manche Heroes sind junge Hoffnungsträger, andere Soldaten auf einer Mission, wieder andere Volkshelden. Doch alle sind reinen Herzens und starken Willens."),
  V("Swashbuckler", "Ich suche Abenteuer, Ruhm und ein bisschen Geld. Den Rest überlasse ich euch!", "Street", "Charm, Eloquence, Etiquette, Grace, Insight, Investigation, Athletics, Fight, Dexterity, Shoot", "Acrobat, Panache oder Nail Thrower", "Manche Duelists sind waschechte Abenteurer, die ihr Leben der Jagd nach Ruhm und starken Gefühlen widmen. Diese Swashbucklers, direkt aus billigen Abenteuerromanen entsprungen, wissen immer, wie man eine Lage aufmischt, und auch wenn sie keinen Ärger suchen, kannst du sicher sein, dass der Ärger sie findet! Wie könnten wir unter ihnen die Umbral Ratadores vergessen, die sich Tag für Tag in gefährlichen Corridas messen."),
  V("Virtuoso", "Wir sind, was wir wiederholt tun. Übung macht den Meister.", "Society", "Art, Etiquette, Grace, Care, Athletics, Fight, Will, Caution, Dexterity, Elusion", "Acrobat, Panache oder Gifted Performer", "Virtuosos sind Meisterfechter, die Form und Eleganz über alles stellen. Ihre Anmut ist legendär, und ihre Disziplin ist ohnegleichen. Unter ihnen gibt es die Sportler, die sich bei Fechtwettkämpfen und Turnieren in Faeriyev und Viletia messen. Aber auch die Leibwächter im Dienst von Adligen und Kaufleuten, die perfekte Verbindung von Form und Substanz."),
  V("Rebel", "Wir werden uns niemals beugen und niemals ergeben. Das Volk verdient Gerechtigkeit!", "Street", "Eloquence, Grace, Care, Insight, Fight, Strength, Will, Caution, Elusion, Exploration", "Well-Trained, From the Gutter oder Selfless", "Ob allein oder mit einer fröhlichen Schar, ob mit oder ohne Maske: Rebels sind stets bereit, gegen die Reichen und Mächtigen zu kämpfen und stehen unerschütterlich auf der Seite des Volkes. Manche nennen sie Verbrecher, andere Helden. Was auch immer die Wahrheit ist: Diese Duelists zögern nie, ihr Leben für die Sache aufs Spiel zu setzen.")]}
]},

{id: "handlers", t: "Animal Handlers", p: 70, b: [
 "Wenn Hunters die Aufgabe haben, die wilden Lande zu erkunden und die Allgemeinheit vor aggressiven Bestien zu schützen, widmen Handlers ihr Leben dem Aufziehen, Hüten, Trainieren und Pflegen von Tieren und Insekten, die friedlich mit Littlings zusammenleben können. Könntet ihr euch das House ohne Reitmäuse, ohne Gecko-Shows, ohne Haushummeln oder ohne Wachkäfer vorstellen? Die Anwesenheit dieser Geschöpfe in unserem Alltag ist so tief verwurzelt, dass wir sie fast für selbstverständlich halten, doch es brauchte Jahrzehnte der Arbeit von Animal Handlers, sie möglich zu machen.",
 "Das ist der Beruf derer, die ihr Leben der Pflege eines oder mehrerer Tiere widmen, derer, die eine Ranch oder einen Hof führen, ebenso aller Tierärzte in ihren Praxen und derer, die bei Hof oder in der Armee dienen. Es sind die Mausknechte, die Leute, die Mäuse zum Bewachen von Häusern oder zur Jagd abrichten, und die, die Ratten für die Arenen in Umbral vorbereiten und ausstaffieren. Es gibt aber auch Littlings, die Haushummeln oder Hornissen züchten, Packkäfer oder Kriegskäfer zähmen und abrichten, und schließlich die Gecko-Dompteure, die mit ihren Wandershows durch das House ziehen.",
 {t: "h", x: "Animal Companion"},
 "Jeder Animal Handler beginnt in Kapitel I mit einem Animal Companion seiner Wahl aus diesen vieren: Beetle, Bumblebee, Gecko oder Mouse. Diese Tiere werden von derselben Person gespielt, die den Animal Handler spielt, und können nur für kleine oder einfache Aktionen selbstständig handeln. Sobald ein Wurf verlangt wird, müssen Handler und Animal Companion immer gemeinsam handeln: mit dem Skill des Animal Handlers, wobei das Tier ihn nach Möglichkeit unterstützt. Jeder Animal Companion verschafft viele Vorteile, bietet Hilfe oder Free Re-rolls in bestimmten Situationen, wie im Trait Animal Companion beschrieben.",
 {t: "h", x: "Traits und Moves"},
 "Jeder Animal Companion hat eigene Traits und Moves, die du auf den späteren Seiten findest. Die Traits und Moves eines Animal Companion können selbstverständlich nur genutzt werden, wenn das Tier auch anwesend ist. In Kapitel I kann ein Animal Handler einen Trait aus denen seiner Berufung oder aus denen seines Animal Companion wählen. Ebenso kann er im Lauf der Kapitel wählen, ob er neue Traits für sich selbst nimmt oder Traits für seinen treuen Animal Companion hinzufügt. Ein Animal Handler kann keine berufsspezifischen Moves wählen, aber er kann Moves für seinen Animal Companion lernen, indem er aus dessen Liste wählt.",
 {t: "h", x: "Der Beruf"},
 {t: "box", h: "Animal Handler", b: ["**Field Point:** Society {herz}", "**Trait:** Animal Companion", "**Wähle einen Move:** unter denen deines Animal Companion", "**Skill Points:** Charm, Eloquence, Care, Insight, Authority, Fight, Will, Caution, Elusion, Exploration"]},
 {t: "h", x: "Berufungen"},
 {t: "karten", x: [
  V("Veterinarian", "Wie geht es deiner Pfote heute? Sieht so aus, als wäre schon alles wieder gut!", "Academia", "Grace, Care, Culture, Investigation, Athletics, Fight, Strength, Will, Caution, Dexterity", "Physician, Kind Soul", "Veterinarians sind ohne Zweifel die bekanntesten und beliebtesten Animal Handlers des Household, denn ihre geschickten Hände können unsere tierischen Freunde behandeln und heilen. Manche dieser Littlings kümmern sich um die äußerst empfindlichen Hummeln, die bei Schönheitswettbewerben antreten. Andere, bescheidenere, leben auf Höfen und versorgen Arbeitsmäuse und Käfer, sind aber genauso beliebt.", AC),
  V("Trainer", "Komm, noch mal von vorn. Du machst das großartig!", "War", "Etiquette, Culture, Investigation, Authority, Fight, Strength, Will, Dexterity, Elusion, Shoot", "Tough as a Nail, Braveheart", "Jede Armee des Household umfasst mindestens ein Bataillon aus hochtrainierten Tieren und ihren Handlern. Unter diesen vier- oder mehrbeinigen Soldaten sind die großen Mäuse der Hearth-Kavallerie und die Sturmkäfer der Porcelain Army. Es gibt aber auch die Hummeln der Black Legion der Horde Army und schließlich die stillen Geckos, die den Sentries der Great Imperial Army helfen.", AC),
  V("Aristocrat", "Alle bei Hof sind arrogant und eingebildet … Nur du verstehst mich, kleiner Fellball.", "Academia", "Art, Charm, Eloquence, Etiquette, Grace, Culture, Investigation, Authority, Elusion, Shoot", "Well-Mannered, Polyglot", "Jeder Hof ist voller falscher Freunde, Blender auf der Suche nach leichtem Geld und Emporkömmlinge aller Art. Es überrascht nicht, dass viele Adlige ein vertrautes Haustier als besten Freund haben, jemanden, der sie um ihrer selbst willen liebt und nicht wegen ihrer Adelstitel. Ein leuchtendes Beispiel dieser Tradition ist Viscount Oleg Protopopolov, der sein Familienerbe ausgab, um den Astraviya Zoological Garden zu bauen.", AC),
  V("Street Performer", "Nein, nicht alle haben dich angesehen. Sie haben mich angesehen! Du bist so eine Diva …", "Street", "Art, Grace, Care, Craft, Insight, Investigation, Athletics, Fight, Dexterity, Elusion", "Gifted Performer, Acrobat", "In den größten Städten des House arbeiten viele Street Performers, besonders während der großen Feste wie Litha und Beltane. Diese Akrobaten, Straßenmusikanten und fahrenden Musiker können sich immer auf ein lustiges Haustier als Assistenten, ja sogar als Star ihrer Show verlassen. Die Verbindung zwischen diesen Animal Handlers und ihren Gefährten ist so groß, dass man nicht anders kann, als verzaubert zu sein!", AC),
  V("Rancher", "Wieder ein harter Arbeitstag, was? Wenigstens habe ich dich zum Helfen.", "War", "Care, Craft, Insight, Investigation, Athletics, Strength, Caution, Dexterity, Exploration, Shoot", "Big and Strong, Pathfinder", "Die großen Ranches und Höfe bei Stairside und auf den Carpet Plains haben die Landschaft des House dauerhaft geprägt. Hier schuften und schwitzen Ranchers, um Vieh zu hüten, auf die Weide zu führen oder vor wilden Bestien zu schützen. Diese Animal Handlers hätten ohne die Hilfe eines treuen Freundes sicher keine Chance, ihre harte Arbeit zu vollbringen!", AC),
  V("Traveling Merchant", "Kommt her, kommt alle her! Hier gibt es Wunder zu sehen! Nur beste Angebote!", "Street", "Eloquence, Etiquette, Craft, Culture, Insight, Investigation, Authority, Will, Caution, Shoot", "Mediator, Perfect Liar", "Traveling Merchants, die mit ihren Waren durch das House ziehen, sind inzwischen fast eine Institution. Manche verkaufen echte Schätze, die sie auf monatelangen Abenteuern in entlegenen Regionen gefunden haben. Andere wollen dir nur wertlosen Plunder und Flitter andrehen. Jedenfalls reisen alle mit einem Tier, meist einem sehr großen. Und wie könnte es anders sein, wenn man die Langeweile einer endlosen Alleinreise bewältigen muss?", AC)]}
]},

{id: "beetle", t: "Beetle", p: 74, b: [
 "Manche Beetles sind so klein, dass man sie auf der Schulter tragen kann, andere fast so groß wie Ratten und können geritten werden. Manche haben kleine scharfe Hörner, andere furchterregend vorstehende Kiefer. Manche sind grün, braun und erdfarben, andere haben einen schimmernden metallischen Panzer. Alle sind starke und robuste Animal Companions, und ihr Hang zur Disziplin führt dazu, dass sie sogar an der Soap-Bubble-Station in Astraviya und in den numismatischen Minen der Vanity eingesetzt werden.",
 {t: "h", x: "Animal Companion: Beetle"},
 "Wählst du einen Beetle als Animal Companion, kannst du ihn so in deiner Ausrüstung notieren:",
 {t: "box", h: "Beetle", b: ["Hilfreich beim Klettern oder Zerbrechen von Gegenständen.", "Du hast einen Free Re-roll, wann immer du und dein Beetle gemeinsam einen Gegner angreift oder euch gegen ihn verteidigt. Wird jemand bedroht, wirf einen Würfel. Zeigt er {kreuz}, ignoriert der Beetle alle Befehle und stürmt mit gesenktem Kopf los, um dich zu verteidigen."]},
 {t: "h", x: "Beetle-Traits"},
 {t: "karten", x: [
  {t: "box", h: "Stern Presence", b: ["Dank deines Beetles hast du immer einen Free Re-roll, wenn du würfelst, um andere zu inspirieren oder einzuschüchtern."]},
  {t: "box", h: "Broadback", b: ["Der Beetle ist groß genug, um geritten zu werden. Er ist hilfreich beim Tragen von Sachen und kann als Partial Cover dienen, um Kugeln auszuweichen, ist aber hinderlich, wenn du dich verstohlen oder auf engem Raum bewegst."]},
  {t: "box", h: "Horns and Jaws", b: ["Dein Beetle ist hilfreich, um Dinge hochzuhieven, zu schleifen oder zu zerschmettern. Außerdem erhältst du +1 auf alle Action Rolls in einer Rangelei."]},
  {t: "box", h: "Fierce", b: ["Dank deines Beetles hast du, nachdem du deine Crucial Box ausgefüllt hast, +1 auf deinen nächsten Action oder Reaction Roll. Von da an ignorierst du alle Zustände, bis du den Stress abgebaut hast."]}]},
 {t: "h", x: "Beetle-Moves"},
 {t: "karten", x: [
  M("Hold the Ground", "dc", "Alle deine Freunde erhalten +1 auf ihren nächsten Reaction Roll gegen einen Gegner."),
  M("Avenge", "c", "Nach einem misslungenen Reaction Roll gegen einen Gegner verursachst du bei ihm 1 Stress."),
  M("Endurance", "dc", "Eine Figur kann entweder vermeiden, den Zustand Verletzt zu erleiden, oder vermeiden, wegen eines Gegners Stress anzusammeln."),
  M("Flying Charge", "c", "Beim ersten Angriff auf einen Gegner verursachst du 1 zusätzlichen Stress."),
  M("Smash", "c", "Entweder kannst du nach einem Treffer auf einen Gegner einen zweiten Action Roll mit −1 ablegen, oder du brichst durch eine Tür oder Wand."),
  M("Ironclad Resistance", "hc", "Du oder ein Freund weicht automatisch einigen Kugeln, einem Angriff oder einem Move eines Large-, Huge-, Giant- oder Flying-Gegners aus, ohne zu würfeln.")]}
]},

{id: "bumblebee", t: "Bumblebee", p: 75, b: [
 "Das ultimative Sinnbild für Schönheit und Eleganz: Bumblebees sind wunderbare Animal Companions und ein großer Hit in den Hallen der High Society. Besonders im Realm ist es unter Adligen üblich, eines dieser Haustier-Insekten zu besitzen und es bei Schönheitswettbewerben oder Geschicklichkeitsprüfungen antreten zu lassen. Es gibt aber auch schwarze Bumblebees, genannt Hornet Bumblebees, und die sind wahrhaft furchterregend. In der Horde gibt es sogar ein ganzes Bataillon dieser Insekten, bekannt als Black Legion.",
 {t: "h", x: "Animal Companion: Bumblebee"},
 "Wählst du eine Bumblebee als Animal Companion, kannst du sie so in deiner Ausrüstung notieren:",
 {t: "box", h: "Bumblebee", b: ["Hilfreich, um das Gleichgewicht zu halten oder kleine Gegenstände zu holen. Sie erlaubt dir, Ziele in kurzer Distanz wie mit einer Wurfwaffe zu treffen.", "Du hast einen Free Re-roll, wann immer du mit deiner Bumblebee aus der Ferne triffst. Ist etwas Süßes in der Nähe, wirf einen Würfel. Zeigt er {herz}, ignoriert die Bumblebee alle Befehle, um es zu fressen."]},
 {t: "h", x: "Bumblebee-Traits"},
 {t: "karten", x: [
  {t: "box", h: "Cute Little Antennae", b: ["Dank deiner Bumblebee hast du immer einen Free Re-roll, wenn du würfelst, um zu bezaubern oder bei anderen einen guten Eindruck zu machen."]},
  {t: "box", h: "Scary Jaws", b: ["Dank deiner Bumblebee hast du immer einen Free Re-roll, wenn du würfelst, um jemanden einzuschüchtern oder zu verhören."]},
  {t: "box", h: "Queen Bumblebee", b: ["Die Bumblebee ist hilfreich im Umgang mit der High Society, aber hinderlich in den Slums."]},
  {t: "box", h: "Sharp Sting", b: ["Die Bumblebee erlaubt dir, Ziele in Reichweite wie mit einer Fernkampfwaffe zu treffen."]}]},
 {t: "h", x: "Bumblebee-Moves"},
 {t: "karten", x: [
  M("Fly Like a Butterfly", "hc", "Du kannst gegen einen Gegner mit Grace +1 reagieren, statt mit dem verlangten Skill."),
  M("Flying Help", "dc", "Eine Figur erklimmt eine Wand, hält ihr Gleichgewicht oder vermeidet die Folgen eines Sturzes, ohne zu würfeln."),
  M("Cuteness Overload", "hd", "Entweder entferne von einer Figur den Zustand Beschämt oder Verängstigt, oder muntere jemanden auf."),
  M("Sting like a Bee", "c", "Ein Gegner in Reichweite erleidet 1 Stress."),
  M("Inspire", "h", "Gib einer Figur +1 auf ihren nächsten Action Roll."),
  M("Hive Mind", "d", "Hat ein Freund einen Wurf bestanden, bestehst du denselben Wurf, ohne zu würfeln.")]}
]},

{id: "gecko", t: "Gecko", p: 76, b: [
 "Von allen Animal Companions sind Geckos zweifellos die verschmitztesten, und oft erweisen sie sich als ebenso klug wie gerissen! Manche dressieren diese Reptilien für Wandershows, andere bringen ihnen sogar bei, unglücklichen Passanten etwas zu stehlen. Seit Kurzem werden Geckos als Haustiere stark nachgefragt, dank des berühmten Romans „Die Geschichte einer Bumblebee und des Geckos, der ihr das Fliegen beibrachte“, der im Household viele Herzen schmelzen ließ.",
 {t: "h", x: "Animal Companion: Gecko"},
 "Wählst du einen Gecko als Animal Companion, kannst du ihn so in deiner Ausrüstung notieren:",
 {t: "box", h: "Gecko", b: ["Hilfreich, um abzulenken, kleine Gegenstände zu greifen oder zu verstecken oder bei Spielen zu schummeln.", "Du hast einen Free Re-roll, wann immer du und dein Gecko versuchen, etwas zu stehlen. Ist etwas Glänzendes in der Nähe, wirf einen Würfel. Zeigt er {pik}, ignoriert der Gecko alle Befehle und rennt los, um es zu stehlen und in seinem Maul zu verstecken."]},
 {t: "h", x: "Gecko-Traits"},
 {t: "karten", x: [
  {t: "box", h: "Carnival Gecko", b: ["Dank deines Geckos hast du immer einen Free Re-roll, wenn du würfelst, um zu tanzen oder aufzutreten."]},
  {t: "box", h: "Extendable Tongue", b: ["Erlaubt dir, Ziele in kurzer Distanz wie mit einer Waffe mit Reichweite zu treffen."]},
  {t: "box", h: "Camouflage Skin", b: ["Der Gecko hilft dir, dich zu verstecken und zu tarnen, solange du still bleibst."]},
  {t: "box", h: "Prehensile Tail", b: ["Der Gecko hilft dir, Schlösser zu knacken und Gadgets zu reparieren oder zu bauen."]}]},
 {t: "h", x: "Gecko-Moves"},
 {t: "karten", x: [
  M("Give a Sticky Hand", "s", "Erhalte +1 auf deinen nächsten Wurf."),
  M("Grab it", "s", "Stiehl oder hole einen kleinen Gegenstand."),
  M("Draw Attention", "hs", "Entweder lenke jemanden ab, oder verhindere, dass eine Figur den Zustand Beschämt erleidet."),
  M("Snitch", "ds", "Entweder bitte die Spielleitung um einen Hinweis oder Vorschlag, oder finde den Weak Spot eines Gegners."),
  M("Slip Away", "hs", "Ein Freund trägt die Folgen deines Misserfolgs statt dir."),
  M("Cheap Trick", "c", "Nachdem du einen Littling getroffen hast, kannst du einen zweiten Action Roll mit −1 ablegen.")]}
]},

{id: "mouse", t: "Mouse", p: 77, b: [
 "Treue Reisegefährten und unvergleichliche Spürhunde, schnelle Reittiere und liebevolle Hüter der Höfe: Mice sind zweifellos der beste Freund jedes Littlings. Es war eine dieser Nager, die mutig die Great Stairs überquerte, um eine Ladung Medizin nach Topridge zu bringen. Ihr zu Ehren wurde eine schöne Kalkstein-Statue angefertigt und auf einem der Plätze von Tuberdam für alle sichtbar aufgestellt.",
 {t: "h", x: "Animal Companion: Mouse"},
 "Wählst du eine Mouse als Animal Companion, kannst du sie so in deiner Ausrüstung notieren:",
 {t: "box", h: "Mouse", b: ["Hilfreich, um Spuren zu folgen, Gegenstände zu holen und Hilfe zu finden.", "Du hast einen Free Re-roll, wann immer du und deine Mouse gemeinsam eine Spur suchen oder verfolgen. Eine Mouse widersetzt sich nie den Befehlen ihres Handlers."]},
 {t: "h", x: "Mouse-Traits"},
 {t: "karten", x: [
  {t: "box", h: "Hound Mouse", b: ["Dank deiner Mouse hast du immer einen Free Re-roll, wenn du würfelst, um Lügen aufzuspüren oder einem Hinterhalt auszuweichen."]},
  {t: "box", h: "Reassuring Presence", b: ["Dank deiner Mouse hast du immer einen Free Re-roll, wenn du würfelst, um seelische Zustände zu heilen oder Mut zu zeigen."]},
  {t: "box", h: "Saddle Mouse", b: ["Die Mouse ist groß genug, um geritten zu werden. Sie hilft dir, schwere Gegenstände zu zerschmettern, zu bewegen oder hochzuhieven, ist aber hinderlich, wenn du dich auf engem Raum bewegst."]},
  {t: "box", h: "Fang and Claws", b: ["Du hast einen Free Re-roll, wann immer du und deine Mouse gemeinsam einen Gegner angreift oder euch gegen ihn verteidigt."]}]},
 {t: "h", x: "Mouse-Moves"},
 {t: "karten", x: [
  M("Sniff Around", "ds", "Entweder bitte die Spielleitung um einen Hinweis oder Vorschlag, oder finde den Weak Spot eines Gegners."),
  M("Growl", "hc", "Du kannst gegen einen Gegner mit Will +1 reagieren, statt mit dem verlangten Skill."),
  M("Lick the Wounds", "hd", "Entferne von einer Figur den Zustand Verletzt oder Verängstigt."),
  M("Protect", "c", "Entweder verhindere, dass ein Freund den Zustand Gebrochen oder Verletzt erleidet, oder rette einen Freund davor, Bow Out zu müssen, ohne einen Joker auszugeben."),
  M("Slash", "c", "Nachdem du eine Large-, Huge- oder Giant-Bestie getroffen hast, kannst du einen zweiten Action Roll mit −1 ablegen."),
  M("Warn of Danger", "hs", "Entweder lässt du eine einzelne Figur nach einem misslungenen Wurf einem Hinterhalt ausweichen, oder du ziehst eine Figur aus einer gefährlichen Lage oder lässt sie den Kampf verlassen.")]}
]},

{id: "traits", t: "Traits", p: 78, b: [
 {t: "h", x: "Berufsspezifische Traits"},
 {t: "karten", x: [
  {t: "box", h: "Sharpshooter", b: ["*Berufsspezifischer Trait der Hunters*", "Erhalte einen Free Re-roll für alle Würfe mit einer Fernkampfwaffe oder Feuerwaffe. Außerdem beginnst du in Kapitel I mit einer kostenlosen Feuer- oder Fernkampfwaffe deiner Wahl."]},
  {t: "box", h: "Master at Arms", b: ["*Berufsspezifischer Trait der Soldiers*", "Wähle eine Nahkampfwaffe, zum Beispiel einen Schlüssel, eine Great-Scissor, einen Cocktailspieß, ein Besteckstück usw. Du darfst keine Duellwaffe und kein Keysket wählen, da sie für deine Kampfbedürfnisse viel zu empfindlich sind. Erhalte einen Free Re-roll für alle Würfe, die deine gewählte Waffe betreffen, sowie für alle Action oder Reaction Rolls im Kampf."]},
  {t: "box", h: "Swordfighter", b: ["*Berufsspezifischer Trait der Duelists*", "Wähle eine Duellwaffe, zum Beispiel eine Pin, eine Needle, eine Lancetta oder eine Duell-Halbschere. Erhalte einen Free Re-roll für alle Würfe, die deine gewählte Waffe betreffen, sowie für alle Action oder Reaction Rolls im Kampf. Außerdem beginnst du Kapitel I mit einer kostenlosen Waffe deiner gewählten Art. Sie ist ein Erbstück, mit dem du dich eng verbunden fühlst."]},
  {t: "box", h: "Know-it-all", b: ["*Berufsspezifischer Trait der Scholars*", "Erhalte einen Free Re-roll, wann immer du versuchst, dich an Informationen über das House, seine Geschichte und die berühmten Littlings zu erinnern, die es bewohnen."]},
  {t: "box", h: "Shadow", b: ["*Berufsspezifischer Trait der Criminals*", "Erhalte einen Free Re-roll, wann immer du versuchst, dich zu verstecken, zu schleichen oder jemanden durch eine Stadt zu verfolgen."]},
  {t: "box", h: "Animal Companion", b: ["*Berufsspezifischer Trait der Animal Handlers*", "Wähle einen Animal Companion: Bumblebee, Beetle, Gecko oder Mouse. Bist du mit deinem Animal Companion zusammen, giltst du immer als bewaffnet. Du kannst den Animal Companion deiner Figur frei bewegen und ihn kleine Aufgaben erledigen oder einfache Aktionen ausführen lassen, etwa jemanden ablenken oder Wache stehen. Außerdem kann sich jeder Animal Companion in manchen Situationen als hilfreich erweisen und dir Free Re-rolls verschaffen. Zusätzliche Informationen zu Animal Companions findest du in ihren jeweiligen Abschnitten in diesem Kapitel."]}]},
 {t: "h", x: "Traits"},
 {t: "karten", x: [
  {t: "box", h: "Acrobat", b: ["Erhalte einen Free Re-roll bei akrobatischen Kunststücken oder wenn du einen Sturz abfängst."]},
  {t: "box", h: "Alert", b: ["Erhalte einen Free Re-roll, um einem Hinterhalt oder einer Gefahr auszuweichen oder wenn du versuchst, Feinde aufzuspüren."]},
  {t: "box", h: "Beastmaster", b: ["Erhalte einen Free Re-roll für alle Action oder Reaction Rolls im Kampf gegen Large-, Huge- oder Giant-Bestien."]},
  {t: "box", h: "Big and Strong", b: ["Erhalte +1, um etwas zu heben, zu tragen oder zu zerbrechen."]},
  {t: "box", h: "Braveheart", b: ["Erhalte +1, wenn du Mut oder starken Willen zeigen musst."]},
  {t: "box", h: "Brawler", b: ["Erhalte einen Free Re-roll und ignoriere Zustände in einer Rangelei."]},
  {t: "box", h: "Camouflage", b: ["Erhalte +1, wenn du dich in der Wildnis tarnst."]},
  {t: "box", h: "Counterfeiter", b: ["Erhalte +1, wenn du versuchst, etwas zu fälschen."]},
  {t: "box", h: "Deadeye", b: ["Mit einer Feuer- oder Fernkampfwaffe ignorierst du alle Nachteile von Partial Cover und des Opponent Traits Nimble."]},
  {t: "box", h: "Engineer", b: ["Erhalte einen Free Re-roll, wenn du versuchst, etwas zu bauen oder zu reparieren."]},
  {t: "box", h: "Forensic Science", b: ["Erhalte +1, wenn du einen Tatort analysierst."]},
  {t: "box", h: "From the Gutter", b: ["Du kennst die Slums und weißt, wie man mit Kriminellen und ihresgleichen umgeht. Erhalte einen Free Re-roll im Umgang mit den Slums."]},
  {t: "box", h: "Gifted Performer", b: ["Wähle eine Kunstform (zum Beispiel Malerei, Tanz, Klavier …). Erhalte einen Free Re-roll, wenn du in deiner gewählten Kunstform auftrittst."]},
  {t: "box", h: "Hard to Kill", b: ["Nachdem du die Crucial Box ausgefüllt hast, erhältst du +1 auf deinen nächsten Action oder Reaction Roll. Von da an ignorierst du alle Zustände, bis du den Stress abgebaut hast."]},
  {t: "box", h: "Heartbreaker", b: ["Erhalte einen Free Re-roll beim Verführen."]},
  {t: "box", h: "Kind Soul", b: ["Erhalte +1, wenn du versuchst, jemanden aufzumuntern, oder seelische Zustände (zum Beispiel Beschämt) entfernst."]},
  {t: "box", h: "Librarian", b: ["Erhalte +1 und ignoriere Zustände, wenn du in einem Buch oder einer Bibliothek nach Informationen suchst, schnell liest oder einen Text übersetzt."]},
  {t: "box", h: "Master Artisan", b: ["Wähle ein Handwerk (zum Beispiel Tischlerei, Kochen, Goldschmiedekunst …). Erhalte einen Free Re-roll im Umgang mit deinem Handwerk."]},
  {t: "box", h: "Mediator", b: ["Erhalte +1, wann immer du versuchst, einen Kompromiss zu finden oder einen Handel abzuschließen."]},
  {t: "box", h: "Nail Thrower", b: ["Erhalte +1 beim Einsatz von Wurfwaffen."]},
  {t: "box", h: "Natural Born Leader", b: ["Erhalte +1 und ignoriere Zustände, wenn du andere inspirierst oder koordinierst."]},
  {t: "box", h: "Panache", b: ["Erhalte einen Free Re-roll, wann immer du versuchst, Eleganz und Haltung zu zeigen, dein Decorum zu erhöhen oder dich anmutig zu verhalten."]},
  {t: "box", h: "Pathfinder", b: ["Erhalte +1, wenn du Spuren suchst oder dich in der Wildnis orientierst."]},
  {t: "box", h: "Perfect Liar", b: ["Erhalte einen Free Re-roll beim Lügen."]},
  {t: "box", h: "Physician", b: ["Erhalte einen Free Re-roll, wann immer du versuchst, eine Diagnose zu stellen, zu operieren oder körperliche Zustände (wie Verletzt oder Krank) zu heilen."]},
  {t: "box", h: "Picklock", b: ["Erhalte +1, um Türen oder Behälter aufzuschließen."]},
  {t: "box", h: "Pickpocket", b: ["Erhalte +1, um jemandem etwas zu stehlen."]},
  {t: "box", h: "Polyglot", b: ["Du kennst zwei zusätzliche Sprachen."]},
  {t: "box", h: "Selfless", b: ["Erhalte einen Free Re-roll, wenn du versuchst, Bedürftigen zu helfen oder sie zu retten. Misslingt es dir, erleidest du 1 zusätzlichen Stress."]},
  {t: "box", h: "Sixth Sense", b: ["Erhalte +1, um die Absichten eines Littlings zu verstehen, ihn zu befragen und Lügen zu durchschauen."]},
  {t: "box", h: "Tough as a Nail", b: ["Erhalte +1 und ignoriere Zustände, wenn du jemanden einschüchterst oder Einschüchterung widerstehst."]},
  {t: "box", h: "Well-mannered", b: ["Du kennst gute Manieren und weißt, wie man sich bei Adligen und Würdenträgern benimmt. Erhalte einen Free Re-roll im Umgang mit der High Society."]},
  {t: "box", h: "Well-Trained", b: ["Erhalte einen Free Re-roll beim Rennen, Klettern oder Schwimmen."]}]},
 {t: "box", h: "Einen Trait erhalten", b: ["In Kapitel I erhalten alle Figuren einen berufsspezifischen Trait, der von ihrem Beruf abhängt, und einen Trait ihrer Wahl aus denen ihrer Berufung.", "Erreichen die Figuren Kapitel III und V, erhalten sie einen neuen Trait ihrer Wahl, den sie frei aus der Liste der Traits aussuchen können. In der Advancement-Phase können Figuren keine neuen berufsspezifischen Traits erhalten."]}
]}
);
})();
